{
  "name": "opencode-adversary",
  "version": "0.2.0",
  "description": "Security plugin for OpenCode with pattern detection and LLM adversary mode",
  "main": "src/index.ts",
  "types": "src/index.ts",
  "files": [
    "src",
    "defaults"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "security",
    "prompt-injection",
    "adversary",
    "guardrail"
  ],
  "author": "crainte",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/crainte/opencode-adversary.git"
  },
  "bugs": {
    "url": "https://github.com/crainte/opencode-adversary/issues"
  },
  "homepage": "https://github.com/crainte/opencode-adversary#readme",
  "funding": {
    "type": "github",
    "url": "https://github.com/sponsors/crainte"
  },
  "engines": {
    "node": ">=18.0.0"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.0.0"
  },
  "devDependencies": {
    "@biomejs/biome": "^2.0.0",
    "@opencode-ai/plugin": "^1.14.0",
    "@types/bun": "^1.3.14",
    "@types/node": "^20.0.0",
    "typescript": "^5.0.0"
  },
  "scripts": {
    "test": "bun test",
    "test:watch": "bun test --watch",
    "test:coverage": "bun test --coverage",
    "typecheck": "tsc --noEmit",
    "lint": "biome check .",
    "lint:fix": "biome check --write .",
    "format": "biome format --write .",
    "prepublishOnly": "npm run typecheck && npm run lint && npm run test"
  }
}
